def factorial(n):
    if n == 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))

def average(numbers):
    return sum(numbers) / len(numbers)

print(average([10, 20, 30, 40, 50]))

def square_list(numbers):
    return [n * n for n in numbers]

print(square_list([1,2,3,4,5]))

